// ── CH1 · PUPS DISCOVERY — backyard, golden butterfly, portal ──

svg += `<defs>
  <linearGradient id="lg-ch1" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${isN ? '#0A1628' : sc.sky1}"/>
    <stop offset="100%" stop-color="${isN ? '#1A2A48' : sc.sky2}"/>
  </linearGradient>
  <radialGradient id="rg-portal" cx="50%" cy="50%">
    <stop offset="0%" stop-color="rgba(255,215,0,0.6)"/>
    <stop offset="40%" stop-color="rgba(147,112,219,0.3)"/>
    <stop offset="100%" stop-color="rgba(147,112,219,0)"/>
  </radialGradient>
</defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-ch1)"/>`;

// Clouds
for (let i = 0; i < 4; i++) {
  const clx = (w * 0.05 + i * w * 0.25 + mt * 6) % (w + 80) - 40;
  const cly = h * 0.08 + Math.sin(i * 2.3) * h * 0.03;
  const clr = 22 + Math.sin(i * 1.7) * 6;
  svg += `<ellipse cx="${clx}" cy="${cly}" rx="${clr}" ry="${clr*0.45}" fill="#FFF" opacity="${isN?0.15:0.65}"/>`;
  svg += `<ellipse cx="${clx-clr*0.4}" cy="${cly+2}" rx="${clr*0.6}" ry="${clr*0.3}" fill="#FFF" opacity="${isN?0.1:0.55}"/>`;
}

// Sun
if (!isN) {
  const sunPulse = 30 + w1 * 8;
  svg += `<circle cx="${w*0.85}" cy="${h*0.1}" r="${sunPulse}" fill="#FFE082" opacity="0.15"/>`;
  svg += `<circle cx="${w*0.85}" cy="${h*0.1}" r="18" fill="#FFE082" opacity="0.55"/>`;
  for (let i = 0; i < 8; i++) {
    const ra = i * Math.PI/4 + mt*0.15;
    svg += `<line x1="${w*0.85+Math.cos(ra)*24}" y1="${h*0.1+Math.sin(ra)*24}" x2="${w*0.85+Math.cos(ra)*(32+w1*4)}" y2="${h*0.1+Math.sin(ra)*(32+w1*4)}" stroke="#FFE082" stroke-width="2" opacity="0.3" stroke-linecap="round"/>`;
  }
}

// Ground
svg += `<rect x="0" y="${bY-5}" width="${w}" height="${h-bY+5}" fill="${sc.ground}"/>`;
for (let i = 0; i < 25; i++) {
  const gx = w*(i/25);
  const gsway = Math.sin(mt*1.2+i*0.7)*2;
  svg += `<line x1="${gx}" y1="${bY}" x2="${gx+gsway}" y2="${bY-5-Math.sin(i*0.9)*3}" stroke="#5AA05A" stroke-width="1.5" stroke-linecap="round" opacity="0.45"/>`;
}
for (let i = 0; i < 6; i++) svg += `<ellipse cx="${w*(0.08+i*0.16)}" cy="${bY+12+Math.sin(i*2.1)*4}" rx="16" ry="4" fill="#8AD48A" opacity="0.25"/>`;

// ── QUEENSLANDER HOUSE (left, background) ──
const hx = w*0.05, hy = bY-5, hw2 = w*0.28, hh2 = 75;
for (let i = 0; i < 4; i++) svg += `<rect x="${hx+i*(hw2/3)-2}" y="${hy-8}" width="4" height="18" fill="#8B7355"/>`;
svg += `<rect x="${hx-3}" y="${hy-hh2}" width="${hw2+6}" height="${hh2-8}" rx="2" fill="${sc.bld}" stroke="#B8986A" stroke-width="${ol}"/>`;
svg += `<polygon points="${hx-10},${hy-hh2} ${hx+hw2/2},${hy-hh2-25} ${hx+hw2+10},${hy-hh2}" fill="#8B4513" stroke="#6B3010" stroke-width="${ol}"/>`;
for (let i = 0; i < 3; i++) {
  const wxp = hx+8+i*(hw2*0.3);
  const winP = Math.sin(mt*1.5+i*1.9)*0.5+0.5;
  svg += `<rect x="${wxp}" y="${hy-hh2+30}" width="16" height="18" rx="1" fill="${isN?`rgba(255,220,120,${0.4+winP*0.5})`:'rgba(135,206,235,0.3)'}" stroke="#B8986A" stroke-width="${ol*0.5}"/>`;
}
svg += `<rect x="${hx+hw2*0.4}" y="${hy-hh2+38}" width="12" height="22" rx="1" fill="#C45A3A" stroke="#8B3A1A" stroke-width="${ol*0.5}"/>`;

// ── TRAMPOLINE (right side) ──
const ttx = w*0.78, tty = bY;
svg += `<line x1="${ttx-25}" y1="${tty}" x2="${ttx-20}" y2="${tty-16}" stroke="#666" stroke-width="2"/>`;
svg += `<line x1="${ttx+25}" y1="${tty}" x2="${ttx+20}" y2="${tty-16}" stroke="#666" stroke-width="2"/>`;
const tbounce = Math.sin(mt*3)*1.5;
svg += `<ellipse cx="${ttx}" cy="${tty-16+tbounce}" rx="28" ry="5" fill="#2A2A2A" stroke="#444" stroke-width="${ol*0.4}"/>`;

// ── HILLS HOIST ──
const hlx2 = w*0.58, hly2 = bY, hlh2 = 45;
svg += `<line x1="${hlx2}" y1="${hly2}" x2="${hlx2}" y2="${hly2-hlh2}" stroke="#888" stroke-width="2.5"/>`;
const hlAng = mt*0.3;
for (let i = 0; i < 4; i++) {
  const a = hlAng + i*(Math.PI/2);
  const ex = hlx2 + Math.cos(a)*24;
  const ey = hly2 - hlh2 + Math.sin(a)*6;
  svg += `<line x1="${hlx2}" y1="${hly2-hlh2}" x2="${ex}" y2="${ey}" stroke="#AAA" stroke-width="1.5"/>`;
  const cSway = Math.sin(mt*1.5+i*1.1)*3;
  const cColors = ['#FF6B6B','#4ECDC4','#FFD166','#9370DB'];
  svg += `<rect x="${(hlx2+ex)/2-3}" y="${(hly2-hlh2+ey)/2}" width="6" height="5" rx="1" fill="${cColors[i]}" opacity="0.8" transform="rotate(${cSway} ${(hlx2+ex)/2} ${(hly2-hlh2+ey)/2})"/>`;
}

// ── Flower bed ──
for (let i = 0; i < 8; i++) {
  const fx = w*0.35+i*14;
  const fy = bY+2;
  const fC = ['#FF6B9D','#FFD166','#FF6B6B','#DA70D6','#FF8C42','#4ECDC4','#9370DB','#87CEEB'][i];
  const fSw = Math.sin(mt*1.2+i*0.9)*2;
  svg += `<line x1="${fx}" y1="${fy}" x2="${fx+fSw}" y2="${fy-9}" stroke="#4A8A4A" stroke-width="1.5"/>`;
  svg += `<circle cx="${fx+fSw}" cy="${fy-11}" r="3" fill="${fC}"/>`;
  svg += `<circle cx="${fx+fSw}" cy="${fy-11}" r="1.5" fill="#FFD700" opacity="0.6"/>`;
}

// ── Fence ──
svg += `<line x1="0" y1="${bY+28}" x2="${w}" y2="${bY+28}" stroke="#C8A878" stroke-width="2"/>`;
for (let i = 0; i < 20; i++) {
  const fxp = i*(w/20)+w*0.025;
  svg += `<rect x="${fxp}" y="${bY+20}" width="4" height="14" rx="1" fill="#D4B888" stroke="#B8986A" stroke-width="${ol*0.2}"/>`;
  svg += `<polygon points="${fxp},${bY+20} ${fxp+2},${bY+17} ${fxp+4},${bY+20}" fill="#D4B888"/>`;
}

// ── EUCALYPTUS TREES (right edge) ──
for (let i = 0; i < 2; i++) {
  const etx = w*0.88+i*22;
  const eth = 55+i*10;
  const sw2 = Math.sin(mt*0.6+i*1.1)*2;
  svg += `<rect x="${etx-3}" y="${bY-eth}" width="6" height="${eth}" rx="2" fill="#8B7355"/>`;
  for (let j = 0; j < 4; j++) {
    const cx2 = etx+Math.sin(j*1.8+i)*9+sw2;
    const cy2 = bY-eth-4+Math.cos(j*1.3)*9;
    svg += `<circle cx="${cx2}" cy="${cy2}" r="${9+Math.sin(j*2.1)*4}" fill="#4A8A5A" stroke="#3A6A3A" stroke-width="${ol*0.3}" opacity="0.7"/>`;
  }
}

// ═══ CHARACTERS ═══

// ── Parent dog (blue heeler) — sitting by house, watching pups ──
const pdx = w*0.22, pdy = bY-3;
svg += `<ellipse cx="${pdx}" cy="${pdy-10}" rx="13" ry="10" fill="#5B8EC4" stroke="#3A6FA0" stroke-width="${ol*0.5}"/>`;
svg += `<circle cx="${pdx+11}" cy="${pdy-18}" r="7.5" fill="#5B8EC4" stroke="#3A6FA0" stroke-width="${ol*0.5}"/>`;
svg += `<polygon points="${pdx+7},${pdy-24} ${pdx+5},${pdy-32} ${pdx+11},${pdy-25}" fill="#4A7AB0"/>`;
svg += `<polygon points="${pdx+15},${pdy-24} ${pdx+17},${pdy-32} ${pdx+13},${pdy-25}" fill="#4A7AB0"/>`;
svg += `<circle cx="${pdx+9}" cy="${pdy-19}" r="1.5" fill="#222"/>`;
svg += `<circle cx="${pdx+14}" cy="${pdy-19}" r="1.5" fill="#222"/>`;
svg += `<ellipse cx="${pdx+11.5}" cy="${pdy-15}" rx="2" ry="1.5" fill="#222"/>`;
svg += `<path d="M${pdx+9} ${pdy-14} Q${pdx+11.5} ${pdy-11} ${pdx+14} ${pdy-14}" fill="none" stroke="#222" stroke-width="1"/>`;
for (let i = 0; i < 4; i++) svg += `<line x1="${pdx-7+i*5}" y1="${pdy-2}" x2="${pdx-7+i*5}" y2="${pdy+3}" stroke="#3A6FA0" stroke-width="2.5" stroke-linecap="round"/>`;
const tailW = Math.sin(mt*4)*12;
svg += `<path d="M${pdx-13} ${pdy-12} Q${pdx-20} ${pdy-22+tailW} ${pdx-17} ${pdy-28+tailW*0.5}" fill="none" stroke="#5B8EC4" stroke-width="3" stroke-linecap="round"/>`;

// ── Pup 1 (orange) — chasing in circles near trampoline ──
const p1angle = mt * 1.5;
const p1x = ttx + Math.cos(p1angle) * 35;
const p1y = bY - 2 + Math.sin(p1angle) * 8;
const p1bob = Math.abs(Math.sin(mt*5))*3;
svg += `<ellipse cx="${p1x}" cy="${p1y-p1bob}" rx="8" ry="6" fill="#FF8C42" stroke="#D06B20" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${p1x+5*Math.cos(p1angle+0.3)}" cy="${p1y-8-p1bob}" r="5.5" fill="#FF8C42" stroke="#D06B20" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${p1x+5*Math.cos(p1angle+0.3)-3},${p1y-12-p1bob} ${p1x+5*Math.cos(p1angle+0.3)-4},${p1y-18-p1bob} ${p1x+5*Math.cos(p1angle+0.3)},${p1y-13-p1bob}" fill="#E07830"/>`;
svg += `<polygon points="${p1x+5*Math.cos(p1angle+0.3)+3},${p1y-12-p1bob} ${p1x+5*Math.cos(p1angle+0.3)+4},${p1y-18-p1bob} ${p1x+5*Math.cos(p1angle+0.3)+1},${p1y-13-p1bob}" fill="#E07830"/>`;
svg += `<circle cx="${p1x+5*Math.cos(p1angle+0.3)-1}" cy="${p1y-9-p1bob}" r="1" fill="#222"/>`;
svg += `<circle cx="${p1x+5*Math.cos(p1angle+0.3)+2}" cy="${p1y-9-p1bob}" r="1" fill="#222"/>`;

// ── Pup 2 (purple) — sniffing at flowers ──
const p2x = w*0.42, p2y = bY;
const p2sniff = Math.sin(mt*2)*3;
svg += `<ellipse cx="${p2x}" cy="${p2y-5}" rx="7" ry="5" fill="#9370DB" stroke="#7B5EA7" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${p2x+5}" cy="${p2y-10+p2sniff}" r="5" fill="#9370DB" stroke="#7B5EA7" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${p2x+2},${p2y-14+p2sniff} ${p2x+1},${p2y-19+p2sniff} ${p2x+5},${p2y-15+p2sniff}" fill="#8060C0"/>`;
svg += `<polygon points="${p2x+8},${p2y-14+p2sniff} ${p2x+9},${p2y-19+p2sniff} ${p2x+6},${p2y-15+p2sniff}" fill="#8060C0"/>`;
svg += `<circle cx="${p2x+4}" cy="${p2y-11+p2sniff}" r="1" fill="#222"/>`;
svg += `<circle cx="${p2x+7}" cy="${p2y-11+p2sniff}" r="1" fill="#222"/>`;
svg += `<ellipse cx="${p2x+5.5}" cy="${p2y-8+p2sniff}" rx="1.5" ry="1" fill="#222"/>`;
const p2tail = Math.sin(mt*3)*8;
svg += `<path d="M${p2x-7} ${p2y-6} Q${p2x-12} ${p2y-14+p2tail} ${p2x-10} ${p2y-18+p2tail*0.5}" fill="none" stroke="#9370DB" stroke-width="2.5" stroke-linecap="round"/>`;
// sniff particles
for (let i = 0; i < 3; i++) {
  const snx = p2x+8+i*3+Math.sin(mt*3+i)*2;
  const sny = p2y-8+p2sniff-i*4;
  svg += `<circle cx="${snx}" cy="${sny}" r="${1+Math.sin(mt*2+i)*0.5}" fill="#FFD700" opacity="${0.3+Math.sin(mt*2.5+i)*0.2}"/>`;
}

// ── Pup 3 (green) — digging near fence ──
const p3x = w*0.65, p3y = bY+2;
const p3dig = Math.abs(Math.sin(mt*4))*4;
svg += `<ellipse cx="${p3x}" cy="${p3y-4}" rx="7" ry="5" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;
svg += `<circle cx="${p3x-4}" cy="${p3y-10}" r="5" fill="#5AAA5A" stroke="#3A8A3A" stroke-width="${ol*0.4}"/>`;
svg += `<polygon points="${p3x-7},${p3y-14} ${p3x-8},${p3y-19} ${p3x-5},${p3y-14}" fill="#4A9A4A"/>`;
svg += `<polygon points="${p3x-1},${p3y-14} ${p3x},${p3y-19} ${p3x-3},${p3y-14}" fill="#4A9A4A"/>`;
svg += `<circle cx="${p3x-5}" cy="${p3y-11}" r="1" fill="#222"/>`;
svg += `<circle cx="${p3x-2}" cy="${p3y-11}" r="1" fill="#222"/>`;
// digging front paws
svg += `<line x1="${p3x-4}" y1="${p3y-5}" x2="${p3x-6}" y2="${p3y+p3dig}" stroke="#3A8A3A" stroke-width="2" stroke-linecap="round"/>`;
// dirt particles flying
for (let i = 0; i < 4; i++) {
  const dirtX = p3x-5+Math.sin(mt*6+i*1.5)*8;
  const dirtY = p3y-2-Math.abs(Math.sin(mt*5+i*1.2))*12;
  svg += `<circle cx="${dirtX}" cy="${dirtY}" r="${1.5+Math.sin(i)*0.5}" fill="#8B7355" opacity="${0.4+Math.sin(mt*4+i)*0.3}"/>`;
}

// ═══ THE GOLDEN BUTTERFLY ═══
// Appears from the flowers, circles around, then heads toward fence
const bfPhase = (mt * 0.4) % 6.28;
const bfx = w*0.42 + Math.sin(bfPhase) * w*0.12 + Math.sin(mt*0.7)*20;
const bfy = bY - 30 + Math.cos(bfPhase*0.8) * 20 + Math.sin(mt*0.5)*10;
const bfWing = Math.sin(mt*7)*5;
// Wings
svg += `<ellipse cx="${bfx-3}" cy="${bfy}" rx="${4+bfWing*0.3}" ry="5" fill="#FFD700" opacity="0.85" transform="rotate(${-bfWing*2} ${bfx-3} ${bfy})"/>`;
svg += `<ellipse cx="${bfx+3}" cy="${bfy}" rx="${4+bfWing*0.3}" ry="5" fill="#FFD700" opacity="0.85" transform="rotate(${bfWing*2} ${bfx+3} ${bfy})"/>`;
svg += `<ellipse cx="${bfx-2}" cy="${bfy+3}" rx="${2.5+bfWing*0.2}" ry="3" fill="#FFA500" opacity="0.7" transform="rotate(${-bfWing*1.5} ${bfx-2} ${bfy+3})"/>`;
svg += `<ellipse cx="${bfx+2}" cy="${bfy+3}" rx="${2.5+bfWing*0.2}" ry="3" fill="#FFA500" opacity="0.7" transform="rotate(${bfWing*1.5} ${bfx+2} ${bfy+3})"/>`;
svg += `<ellipse cx="${bfx}" cy="${bfy}" rx="1" ry="3.5" fill="#8B6914"/>`;
// Butterfly glow trail
for (let i = 0; i < 8; i++) {
  const trx = bfx - Math.sin(bfPhase-i*0.15)*w*0.12*0.3 - i*3;
  const tri = bfy + i*2 + Math.cos(mt*0.6+i*0.4)*3;
  svg += `<circle cx="${trx}" cy="${tri}" r="${2-i*0.2}" fill="#FFD700" opacity="${0.3-i*0.035}"/>`;
}
// Butterfly sparkle aura
const bfGlow = 10 + w3*6;
svg += `<circle cx="${bfx}" cy="${bfy}" r="${bfGlow}" fill="#FFD700" opacity="${0.04+w1*0.03}"/>`;

// ═══ SHIMMERING PORTAL (at fence, right side) ═══
const portalX = w*0.92;
const portalY = bY - 5;
const portalR = 22 + w2 * 8;
const portalPulse = Math.sin(mt*1.5)*0.5+0.5;
// Portal glow
svg += `<circle cx="${portalX}" cy="${portalY-25}" r="${portalR+10}" fill="url(#rg-portal)" opacity="${0.3+portalPulse*0.3}"/>`;
// Portal rings
for (let i = 0; i < 3; i++) {
  const pr = portalR - i*6;
  const pop = 0.3 + Math.sin(mt*2+i*1.2)*0.2;
  const prot = mt*30 + i*40;
  svg += `<ellipse cx="${portalX}" cy="${portalY-25}" rx="${pr}" ry="${pr*1.3}" fill="none" stroke="${['#FFD700','#9370DB','#7DF9FF'][i]}" stroke-width="1.5" opacity="${pop}" transform="rotate(${prot} ${portalX} ${portalY-25})"/>`;
}
// Sparkles around portal
for (let i = 0; i < 10; i++) {
  const spAng = mt*0.8 + i*0.63;
  const spR = portalR + 5 + Math.sin(mt*2+i)*8;
  const spx = portalX + Math.cos(spAng)*spR;
  const spy = portalY - 25 + Math.sin(spAng)*spR*1.3;
  svg += `<circle cx="${spx}" cy="${spy}" r="${1+Math.sin(mt*3+i)*0.5}" fill="${i%2===0?'#FFD700':'#9370DB'}" opacity="${0.3+Math.sin(mt*2.5+i*0.7)*0.3}"/>`;
}

// ── Night extras ──
if (isN) {
  for (let i = 0; i < 20; i++) {
    const stx = (Math.sin(i*93.7+2.1)*0.5+0.5)*w;
    const sty = (Math.sin(i*217.3+5.7)*0.5+0.5)*h*0.3;
    svg += `<circle cx="${stx}" cy="${sty}" r="${0.5+Math.sin(mt*1.5+i*0.6)*0.4}" fill="#FFF" opacity="${0.5+Math.sin(mt+i)*0.3}"/>`;
  }
  for (let i = 0; i < 6; i++) {
    const ffx2 = w*0.2+Math.sin(mt*0.8+i*1.7)*w*0.3;
    const ffy2 = bY-8+Math.cos(mt*0.6+i*1.1)*12;
    svg += `<circle cx="${ffx2}" cy="${ffy2}" r="2" fill="#FFFF88" opacity="${0.3+Math.sin(mt*2.5+i*1.3)*0.3}"/>`;
  }
}
